    shortcut: {
        enable: true,
        handles: {
            // Ctrl+C: 复制节点
            'copy': function(jm, e) {
                var selected_node = jm.get_selected_node();
                if (selected_node && !selected_node.isroot) {
                    // 保存节点信息到剪贴板
                    jm._clipboard = {
                        id: selected_node.id,  // 保存源节点 ID
                        topic: selected_node.topic,
                        data: Object.assign({}, selected_node.data)
                    };
                }
            },

            // Ctrl+V: 粘贴节点
            'paste': function(jm, e) {
                if (!jm._clipboard) return;

                var selected_node = jm.get_selected_node();
                if (!selected_node) return;

                // 1. 创建新节点
                var new_node_id = jsMind.util.uuid.newid();
                var copied_data = Object.assign({}, jm._clipboard.data);

                // 2. 保存源节点引用
                copied_data.source_node_id = jm._clipboard.id;

                // 3. 设置复制节点的颜色以示区别
                copied_data['background-color'] = '#ffcccc';
                copied_data['foreground-color'] = '#000000';

                // 4. 添加复制的节点
                var new_node = jm.add_node(
                    selected_node, 
                    new_node_id, 
                    jm._clipboard.topic, 
                    copied_data
                );

                if (!new_node) return;

                // 5. 更新源节点的复制计数器
                var source_node = jm.get_node(jm._clipboard.id);
                if (source_node) {
                    // 初始化计数器
                    if (!source_node.data.copy_count) {
                        source_node.data.copy_count = 0;
                    }
                    source_node.data.copy_count++;

